proc featureIndex*(slug: string): int =
  ## Index of `slug` in `caniemailFeatures`, or -1 when absent.
  for i, s in caniemailFeatures:
    if s == slug:
      return i
  -1

proc clientIndex*(key: string): int =
  ## Index of `key` (`family/platform`) in `caniemailClients`, or -1.
  for i, k in caniemailClients:
    if k == key:
      return i
  -1

proc supportAt*(fi, ci: int): SupportValue =
  ## Support value at a feature/client index pair.
  case caniemailSupport[fi][ci]
  of 1: svYes
  of 2: svNo
  of 3: svPartial
  else: svUnknown

proc notesAt*(fi, ci: int): seq[int] =
  ## Note ids at a feature/client index pair (empty = none).
  for r in caniemailNoteRefs:
    if r[0] == fi and r[1] == ci:
      result.add(r[2])

proc supportFor*(slug, key: string): tuple[value: SupportValue, notes: seq[int]] =
  ## Support value and note ids for a feature slug and client key.
  ## Unknown slugs or keys read as `(svUnknown, @[])`.
  let fi = featureIndex(slug)
  let ci = clientIndex(key)
  if fi < 0 or ci < 0:
    return (svUnknown, @[])
  (supportAt(fi, ci), notesAt(fi, ci))
